SELECT user_id, username, password, role_id, real_name, status
FROM tb_user
WHERE username = #{username}
  AND role_id = #{roleId}
  AND status = #{status}

SELECT user_id, username, real_name, phone, user_mail, status
FROM tb_user
WHERE username = #{username}
    AND status = #{status}
LIMIT 1
